#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
// Bubble sort implementation
void bubble_sorting(int N, int *arr){
    int hold;
    bool flag_iterate = true;
    int pass = 0;

    while (flag_iterate) {
        pass += 1;
        flag_iterate = false;

        // Bubble sorting pass
        for (int i = 0; i < N - 1; i++) {
            if (arr[i + 1] < arr[i]) {
                flag_iterate = true;
                hold = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = hold;
            }
        }

        // Output the array after each pass
        printf("OUTPUT: ");
        for (int i = 0; i < N; i++) {
            printf("%d ", arr[i]);
        }
        printf("\n");
    }

    printf("Total number of steps: %d\n", pass);
} 

